	public function connection_page() {
		if ( ! current_user_can( 'manage_options' ) ) wp_die( esc_html__( 'Anda tidak memiliki izin.', 'ai-news-assistant' ) );
		$s         = AI_News_Assistant::settings();
		$connected = ! empty( $s['site_token'] );
		$balance   = $connected ? $this->backend_balance( $s ) : null;
		?>
		<div class="wrap aina-wrap aina-account-page">
			<header class="aina-header aina-account-header">
				<div><span class="aina-eyebrow"><?php esc_html_e( 'KONEKSI AKUN', 'ai-news-assistant' ); ?></span><h1><?php esc_html_e( 'Akun AI', 'ai-news-assistant' ); ?></h1><p><?php esc_html_e( 'Kelola akun dan akses layanan AI News Assistant.', 'ai-news-assistant' ); ?></p></div>
				<span class="aina-connection-pill <?php echo $connected ? 'is-connected' : 'is-guest'; ?>"><span class="dashicons <?php echo $connected ? 'dashicons-yes-alt' : 'dashicons-clock'; ?>"></span><?php echo $connected ? esc_html__( 'Connected', 'ai-news-assistant' ) : esc_html__( 'Guest Trial', 'ai-news-assistant' ); ?></span>
