			<?php if ( isset( $_GET['aina_message'] ) ) : ?>
				<div class="aina-account-notice"><span class="dashicons dashicons-info-outline"></span><p><?php echo esc_html( sanitize_text_field( wp_unslash( $_GET['aina_message'] ) ) ); ?></p></div>
			<?php endif; ?>

			<div class="aina-account-grid">
				<section class="aina-panel aina-connection-card">
					<div class="aina-account-card-head"><span class="aina-account-icon"><span class="dashicons dashicons-cloud-saved"></span></span><div><h2><?php echo $connected ? esc_html__( 'Akun Berhasil Terhubung', 'ai-news-assistant' ) : esc_html__( 'Hubungkan Akun', 'ai-news-assistant' ); ?></h2><p><?php echo $connected ? esc_html__( 'Layanan AI aktif dan siap digunakan di website ini.', 'ai-news-assistant' ) : esc_html__( 'Login atau buat akun untuk mengaktifkan layanan penuh.', 'ai-news-assistant' ); ?></p></div></div>

					<form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>" class="aina-account-form">
						<?php wp_nonce_field( 'aina_backend_connection' ); ?>
						<input type="hidden" name="action" value="aina_backend_connection">
						<input type="hidden" name="backend_url" value="<?php echo esc_attr( $s['backend_url'] ); ?>">

						<?php if ( ! $connected ) : ?>
							<div class="aina-account-fields">
								<label class="aina-account-field"><span><?php esc_html_e( 'Nama', 'ai-news-assistant' ); ?> <small><?php esc_html_e( 'untuk registrasi', 'ai-news-assistant' ); ?></small></span><input type="text" name="account_name" autocomplete="name" placeholder="Nama lengkap"></label>
								<label class="aina-account-field"><span><?php esc_html_e( 'Email', 'ai-news-assistant' ); ?></span><input type="email" name="account_email" autocomplete="email" placeholder="nama@email.com" required></label>
							</div>
							<label class="aina-account-field"><span><?php esc_html_e( 'Password', 'ai-news-assistant' ); ?></span><input type="password" name="account_password" autocomplete="current-password" placeholder="Masukkan password akun" required><small class="aina-field-help"><span class="dashicons dashicons-lock"></span><?php esc_html_e( 'Password dikirim saat login dan tidak pernah disimpan di WordPress.', 'ai-news-assistant' ); ?></small></label>
							<div class="aina-account-actions"><button class="button button-primary aina-primary" name="mode" value="login"><span class="dashicons dashicons-migrate"></span><?php esc_html_e( 'Login & Hubungkan', 'ai-news-assistant' ); ?></button><button class="button aina-secondary-button" name="mode" value="register"><span class="dashicons dashicons-plus-alt2"></span><?php esc_html_e( 'Daftar + Bonus Rp5.000', 'ai-news-assistant' ); ?></button></div>
						<?php else : ?>
							<div class="aina-connected-details"><div><span><?php esc_html_e( 'Status akun', 'ai-news-assistant' ); ?></span><strong><i></i><?php esc_html_e( 'Aktif & terhubung', 'ai-news-assistant' ); ?></strong></div><div><span><?php esc_html_e( 'Sisa kredit', 'ai-news-assistant' ); ?></span><strong><?php echo null === $balance ? esc_html__( 'Tidak tersedia', 'ai-news-assistant' ) : esc_html( $this->format_credit( $balance ) ); ?></strong></div><div><span><?php esc_html_e( 'Website aktif', 'ai-news-assistant' ); ?></span><strong><?php echo esc_html( (string) wp_parse_url( home_url(), PHP_URL_HOST ) ); ?></strong></div></div>
							<div class="aina-account-actions"><a class="button button-primary aina-primary" href="<?php echo esc_url( admin_url( 'admin.php?page=ai-news-assistant' ) ); ?>"><span class="dashicons dashicons-edit-page"></span><?php esc_html_e( 'Buka Newsroom', 'ai-news-assistant' ); ?></a><button class="button aina-danger-button" name="mode" value="disconnect" onclick="return confirm('<?php echo esc_js( __( 'Putuskan website dari akun backend?', 'ai-news-assistant' ) ); ?>');"><span class="dashicons dashicons-dismiss"></span><?php esc_html_e( 'Putuskan Koneksi', 'ai-news-assistant' ); ?></button></div>
