	}
	public function handle_backend_connection() { if ( ! current_user_can( 'manage_options' ) ) wp_die( esc_html__( 'Anda tidak memiliki izin.', 'ai-news-assistant' ) ); check_admin_referer( 'aina_backend_connection' ); $s = AI_News_Assistant::settings(); $mode = isset( $_POST['mode'] ) ? sanitize_key( $_POST['mode'] ) : 'save'; $s['backend_url'] = isset( $_POST['backend_url'] ) ? untrailingslashit( esc_url_raw( wp_unslash( $_POST['backend_url'] ) ) ) : $s['backend_url']; $message = __( 'Backend URL tersimpan.', 'ai-news-assistant' ); if ( 'disconnect' === $mode ) { $s['account_token'] = ''; $s['site_token'] = ''; $message = __( 'Connected Site diputus.', 'ai-news-assistant' ); } elseif ( in_array( $mode, array( 'login', 'register' ), true ) ) { $email = isset( $_POST['account_email'] ) ? sanitize_email( wp_unslash( $_POST['account_email'] ) ) : ''; $password = isset( $_POST['account_password'] ) ? (string) wp_unslash( $_POST['account_password'] ) : ''; $body = array( 'email' => $email, 'password' => $password ); if ( 'register' === $mode ) { $body['name'] = isset( $_POST['account_name'] ) ? sanitize_text_field( wp_unslash( $_POST['account_name'] ) ) : ''; $body['password_confirmation'] = $password; } $auth = $this->backend_post( $s['backend_url'] . '/api/auth/' . $mode, $body ); if ( is_wp_error( $auth ) ) $message = $auth->get_error_message(); else { $s['account_token'] = $auth['token']; $site = $this->backend_post( $s['backend_url'] . '/api/sites/connect', array( 'site_name' => get_bloginfo( 'name' ), 'site_url' => home_url(), 'install_id' => AI_News_Assistant::install_id() ), $s['account_token'] ); if ( is_wp_error( $site ) ) $message = $site->get_error_message(); else { $s['site_token'] = $site['site_token']; $message = __( 'Website berhasil terhubung ke akun.', 'ai-news-assistant' ); } } } $this->save_connection_settings( $s ); wp_safe_redirect( add_query_arg( 'aina_message', $message, admin_url( 'admin.php?page=ai-news-assistant-account' ) ) ); exit; }
	private function save_connection_settings( array $settings ) { remove_filter( 'sanitize_option_aina_settings', array( $this, 'sanitize_settings' ) ); update_option( 'aina_settings', $settings ); add_filter( 'sanitize_option_aina_settings', array( $this, 'sanitize_settings' ) ); }
	private function backend_balance( array $settings ) { if ( empty( $settings['backend_url'] ) || empty( $settings['account_token'] ) ) return null; $response = wp_remote_get( untrailingslashit( $settings['backend_url'] ) . '/api/wallet/balance', array( 'timeout' => 10, 'headers' => array( 'Authorization' => 'Bearer ' . $settings['account_token'], 'Accept' => 'application/json' ) ) ); if ( is_wp_error( $response ) ) return null; $json = json_decode( wp_remote_retrieve_body( $response ), true ); return is_array( $json ) && ! empty( $json['success'] ) && isset( $json['data']['balance_amount'] ) ? (float) $json['data']['balance_amount'] : null; }
	private function format_credit( $balance ) { return 'Rp' . number_format( (float) $balance, 0, ',', '.' ); }
	private function backend_post( $url, array $body, $token = '' ) { $headers = array( 'Content-Type' => 'application/json', 'Accept' => 'application/json' ); if ( $token ) $headers['Authorization'] = 'Bearer ' . $token; $response = wp_remote_post( esc_url_raw( $url ), array( 'timeout' => 45, 'headers' => $headers, 'body' => wp_json_encode( $body ) ) ); if ( is_wp_error( $response ) ) return $response; $json = json_decode( wp_remote_retrieve_body( $response ), true ); if ( ! is_array( $json ) || empty( $json['success'] ) ) return new WP_Error( 'aina_backend_auth', isset( $json['message'] ) ? sanitize_text_field( $json['message'] ) : __( 'Backend tidak memberikan respons valid.', 'ai-news-assistant' ) ); return $json['data']; }
}
